# Rebuild the downloadable archive from the tracked source files.
from zipfile import ZipFile, ZIP_DEFLATED
kit = p / 'downloads/kit-xalok'
with ZipFile(p / 'downloads/kit-xalok.zip', 'w', ZIP_DEFLATED) as archive:
    for file in sorted(kit.rglob('*')):
        if file.is_file():
            archive.write(file, file.relative_to(p / 'downloads'))
